      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      sentence = "Childe Kiro!",
      next = {2}
    },
    [2] = {
      beijing = 1747,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "With my skirt hem raised, I trotted through the ruins of a courtyard to the front entrance of an ancient temple. A light breeze met me, sending a sweet melon aroma wafting from my skin.",
      next = {3}
    },
    [3] = {
      beijing = 1747,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "As I ran, I felt a pain in my chest, and my breath turned into a wheeze. I seemed on the verge of an episode from the asthma that had plagued me for years.",
      next = {4}
    },
    [4] = {
      beijing = 1747,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "I frantically rubbed at my chest and shot an inadvertent glance at the run-down ancient temple before me.",
      next = {5}
    },
    [5] = {
      beijing = 1747,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "It was situated underneath a thick canopy of old-growth trees, and the broken beast carvings adorning its eaves accentuated the gloomy air about it.",
      next = {6}
    },
    [6] = {
      beijing = 1747,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "But as dilapidated and peculiar as it was, this temple was the last straw of hope for survival that I could grasp at. Beggar that I was, I had no choice but to grit my teeth and trot forward.",
      next = {7}
    },
    [7] = {
      beijing = 4993,
      bganim = 0,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      ruchang = -1,
      sentence = "As soon as I stepped over the threshold, I caught sight of a golden-haired man reclining on a cushion beneath a statue of the Buddha.",
      next = {8}
    },
    [8] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      sentence = "He was leaning back with his eyes closed. A gaudy, motley robe outlined the contours of his lithe figure, and his bared chest gently rose and fell with his breath.",
      next = {9}
    },
    [9] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      sentence = "Even though I had stared at this face for half a month, seeing it again still managed to captivate my soul.",
      next = {10}
    },
    [10] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "I steadied my breath and squatted down next to the cushion. Then, I rolled up my sleeve and held my forearm up to his nose.",
      next = {11}
    },
    [11] = {
      beijing = 4993,
      dhead = 107,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "I soaked myself in watermelon juice for several hours this morning.",
      next = {12}
    },
    [12] = {
      beijing = 4993,
      dhead = 101,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "Now I smell like your favorite scent from head to toe. Do you wish to partake of me now, Childe?",
      next = {13}
    },
    [13] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176106,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "He didn't say anything, but I knew he was awake. Strips of decorative silk scarf swished back and forth in a leisurely manner like a cat's tail.",
      next = {14}
    },
    [14] = {
      beijing = 4993,
      dhead = 111,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
