      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "But every time I \"marinated\" myself with whatever flavor he desired... he would have a sudden change of heart.",
      next = {21}
    },
    [21] = {
      beijing = 4993,
      dhead = 110,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "So what is it you wish for today? I'll go track it down posthaste.",
      next = {22}
    },
    [22] = {
      beijing = 4993,
      dialog = 2,
      idx = 5,
      male = 3,
      music = "PW_15_PV",
      renming = "Childe Kiro",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "Are you... that set on having me eat you?",
