    },
    [23] = {
      beijing = 4993,
      dialog = 2,
      idx = 5,
      male = 3,
      music = "PW_15_PV",
      renming = "Childe Kiro",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "Are you not afraid that you won't end up turning into a Stray, but rather just become food in my belly?",
