    },
    [24] = {
      beijing = 4993,
      dhead = 112,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "Don't think you can frighten me, Childe. Before coming, I asked the Head Monk, and he told me that \"Stray Devouring\" isn't getting eaten in the literal sense.",
      next = {25}
    },
    [25] = {
      beijing = 4993,
      dhead = 112,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "On the contrary, you envelop a mortal in the stray aura you've cultivated through the centuries; and in a few days, the person can slowly metamorphose into the same type of Stray creature that you are.",
