    },
    [26] = {
      beijing = 4993,
      dialog = 2,
      idx = 5,
      male = 3,
      music = "PW_15_PV",
      renming = "Childe Kiro",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "And so what?",
      voice = 2,
