      dialog = 2,
      idx = 5,
      male = 3,
      music = "PW_15_PV",
      renming = "Childe Kiro",
      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "For all these days you've been coming here, you must know that although I've taken up residence in this temple for nearly a century, that doesn't mean I have to cater to everyone's requests.",
      voice = 2,
      next = {28}
    },
    [28] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "Kiro smiled and crooked his knee, wrapping one leg around the other in a pose just like a model in a classic painting.",
      next = {29}
    },
    [29] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "If I hadn't heard the rumors about this ancient temple, I'd have never believed he was the Stray named Kiro who had started squatting here a hundred years ago.",
      next = {30}
    },
    [30] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "But ever since he commandeered the place, no small number of folks really had boldly stepped forward to request his assistance.",
      next = {31}
    },
    [31] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "A girl yearning for marriage, but being wed to a ghost. A boy wanting a career in government, but being made to serve the emperor as a eunuch.",
