    },
    [32] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "This devilish creature capriciously toyed with us humans, and if I hadn't already sought the help of every physician under the sun... I would never in a million years roll the dice with him.",
