    },
    [33] = {
      beijing = 4993,
      dhead = 101,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      sentence = "Of course, I would never come to you if I wasn't already prepared for the worst.",
