      dhead = 101,
      dialog = 1,
      music = "PW_15_PV",
      renming = "$u",
      renwu = "npc",
      sentence = "Whatever you desire, Childe, just say the word. Your wish is my command.",
      next = {35}
    },
    [35] = {
      beijing = 4993,
      dialog = 3,
      music = "PW_15_PV",
      renwu = "npc",
      sentence = "Kiro let out a laugh, and his fair fingers plucked at the cushion.",
