      renwu = "npc",
      role1 = 3176000,
      role2 = 3176101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "Childe, you're making things difficult on purpose. Tangerines are only available in winter, and I most likely won't be alive that long.",
